{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Tofogliflozin had a mean absolute oral bioavailability of 97.5% in healthy male volunteers using a double-tracer technique with a 20 mg oral dose and IV microdose, supporting high F."
    },
    {
      "card_ids": ["C48"],
      "claim": "Dapagliflozin absolute oral bioavailability was 78% (90% CI 73–83%) in healthy subjects using simultaneous IV 14C-microdose and therapeutic oral dosing, supporting high F."
    },
    {
      "card_ids": ["C13"],
      "claim": "Emtricitabine absolute oral bioavailability was 93% following oral administration in HBV- and HIV-infected patients, supporting high F."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "All ten evidence molecules support high absolute oral bioavailability at the F>=20% threshold after discounting altered fed conditions and provenance-conflicted records; strongest human absolute BA measurements are 78–97.5%.",
  "evidence_gaps": [
    "Molecule 6 groups emtricitabine and didanosine records; didanosine records were discounted as a provenance conflict.",
    "Molecule 2 fed-condition F values (0.17–0.19) are below 20%, but fed is an altered condition; fasting values (0.22–0.28) support high.",
    "Molecule 9 is a predicted estimate (20–30%) without direct clinical measurement, and Molecule 8 is exactly at the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C33", "C48", "C13"],
  "revision_action": "initial",
  "supportive_card_ids": ["C33", "C48", "C13"]
}

